package ai.interviewiq.api.service;

import ai.interviewiq.api.dto.CatalogDtos.*;
import ai.interviewiq.api.dto.InterviewDtos.*;
import ai.interviewiq.api.entity.*;
import ai.interviewiq.api.exception.ApiException;
import ai.interviewiq.api.repository.*;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.data.domain.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service
public class InterviewService {
    private final UserRepository users; private final CompanyRepository companies; private final JobRoleRepository roles; private final DifficultyLevelRepository diffs; private final InterviewTemplateRepository templates; private final InterviewSessionRepository sessions; private final InterviewFeedbackRepository feedbacks; private final QuestionFeedbackRepository questionFeedbacks; private final QuestionProvider questions; private final EvaluationProvider evaluator; private final ObjectMapper json;
    public InterviewService(UserRepository users, CompanyRepository companies, JobRoleRepository roles, DifficultyLevelRepository diffs, InterviewTemplateRepository templates, InterviewSessionRepository sessions, InterviewFeedbackRepository feedbacks, QuestionFeedbackRepository questionFeedbacks, QuestionProvider questions, EvaluationProvider evaluator, ObjectMapper json) { this.users=users;this.companies=companies;this.roles=roles;this.diffs=diffs;this.templates=templates;this.sessions=sessions;this.feedbacks=feedbacks;this.questionFeedbacks=questionFeedbacks;this.questions=questions;this.evaluator=evaluator;this.json=json; }
    @Transactional public SessionResponse create(Long uid, CreateRequest request) { User user=users.getReferenceById(uid); Company company=companies.findById(request.companyId()).filter(Company::isActive).orElseThrow(()->notFound("Company")); JobRole role=roles.findById(request.jobRoleId()).filter(JobRole::isActive).orElseThrow(()->notFound("Job role")); DifficultyLevel difficulty=diffs.findById(request.difficultyLevelId()).filter(DifficultyLevel::isActive).orElseThrow(()->notFound("Difficulty level")); InterviewTemplate template=request.interviewTemplateId()==null?templates.findFirstByIsActiveTrueOrderByIdAsc().orElseThrow(()->notFound("Interview template")):templates.findById(request.interviewTemplateId()).filter(InterviewTemplate::isActive).orElseThrow(()->notFound("Interview template")); InterviewSession session=new InterviewSession(user,company,role,difficulty,template); questions.generate(company,role,difficulty,template).stream().limit(template.getDefaultQuestionCount()).forEach(text->session.addQuestion(new InterviewQuestion(session.getQuestions().size()+1,text,template.getCode()))); session.ready(); return response(sessions.save(session),true); }
    @Transactional(readOnly=true) public SessionResponse get(Long uid,Long id){return response(owned(uid,id),true);}
    @Transactional public SessionResponse start(Long uid,Long id){InterviewSession session=owned(uid,id);if(session.getStatus()!=InterviewStatus.READY)throw conflict("Interview cannot be started in its current state.");session.start();return response(session,true);}
    @Transactional public AnswerResponse answer(Long uid,Long sessionId,Long questionId,AnswerRequest request){InterviewSession session=owned(uid,sessionId);if(session.getStatus()!=InterviewStatus.IN_PROGRESS)throw conflict("Interview is not active.");InterviewQuestion question=session.getQuestions().stream().filter(x->x.getId().equals(questionId)).findFirst().orElseThrow(()->notFound("Question"));if(question.getAnswer()==null)question.setAnswer(new CandidateAnswer(request.answerText().trim(),request.inputMethod()));else question.getAnswer().replace(request.answerText().trim(),request.inputMethod());CandidateAnswer answer=question.getAnswer();return new AnswerResponse(question.getId(),answer.getAnswerText(),answer.getInputMethod(),answer.getSubmittedAt());}
    @Transactional public FeedbackResponse complete(Long uid,Long id){InterviewSession session=owned(uid,id);if(session.getStatus()!=InterviewStatus.IN_PROGRESS)throw conflict("Interview is not active.");if(session.getQuestions().stream().anyMatch(q->q.getAnswer()==null))throw new ApiException(HttpStatus.BAD_REQUEST,"VALIDATION_FAILED","All questions require an answer before completion.");AiEvaluation evaluation=evaluator.evaluate(session);InterviewFeedback feedback=new InterviewFeedback(session);feedback.available(evaluation.overallScore(),evaluation.overallAssessment(),toJson(evaluation.strengths()),toJson(evaluation.improvementAreas()),toJson(evaluation.recommendedActions()));feedback=feedbacks.save(feedback);Map<Long,InterviewQuestion> byId=new HashMap<>();session.getQuestions().forEach(question->byId.put(question.getId(),question));final InterviewFeedback savedFeedback=feedback;questionFeedbacks.saveAll(evaluation.questionFeedback().stream().map(item->new QuestionFeedback(savedFeedback,byId.get(item.questionId()),item.score(),toJson(item.strengths()),toJson(item.improvements()),item.recommendation())).toList());session.complete();return feedback(feedback);}
    @Transactional(readOnly=true) public PageResponse<SessionResponse> history(Long uid,InterviewStatus status,int page,int limit){Pageable pageable=PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,limit)),Sort.by(Sort.Direction.DESC,"createdAt"));Page<InterviewSession> result=status==null?sessions.findByUserId(uid,pageable):sessions.findByUserIdAndStatus(uid,status,pageable);return new PageResponse<>(result.map(item->response(item,false)).toList(),result.hasNext()?String.valueOf(page+1):null,limit);}
    @Transactional(readOnly=true) public List<QuestionResponse> questions(Long uid,Long id){return response(owned(uid,id),true).questions();}
    @Transactional(readOnly=true) public FeedbackResponse feedback(Long uid,Long id){owned(uid,id);return feedback(feedbacks.findByInterviewSessionId(id).orElseThrow(()->notFound("Feedback")));}
    private InterviewSession owned(Long uid,Long id){return sessions.findByIdAndUserId(id,uid).orElseThrow(()->notFound("Interview"));} private ApiException notFound(String name){return new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND",name+" not found.");} private ApiException conflict(String message){return new ApiException(HttpStatus.CONFLICT,"CONFLICT",message);}
    public static SessionResponse response(InterviewSession session,boolean include){List<QuestionResponse> questionList=include?session.getQuestions().stream().map(question->new QuestionResponse(question.getId(),question.getSequenceNumber(),question.getQuestionText(),question.getQuestionType(),question.getAnswer()!=null)).toList():List.of();return new SessionResponse(session.getId(),new CompanyResponse(session.getCompany().getId(),session.getCompany().getCode(),session.getCompany().getName()),new JobRoleResponse(session.getJobRole().getId(),session.getJobRole().getCode(),session.getJobRole().getName(),session.getJobRole().getCategory()),new DifficultyResponse(session.getDifficultyLevel().getId(),session.getDifficultyLevel().getCode(),session.getDifficultyLevel().getDisplayName(),session.getDifficultyLevel().getRankOrder()),new TemplateResponse(session.getInterviewTemplate().getId(),session.getInterviewTemplate().getCode(),session.getInterviewTemplate().getName(),session.getInterviewTemplate().getDefaultQuestionCount()),session.getStatus(),session.getQuestions().size(),(int)session.getQuestions().stream().filter(question->question.getAnswer()!=null).count(),session.getCreatedAt(),session.getStartedAt(),session.getCompletedAt(),questionList);}
    private FeedbackResponse feedback(InterviewFeedback feedback){List<QuestionFeedbackResponse> perQuestion=questionFeedbacks.findByInterviewFeedbackIdOrderByInterviewQuestionSequenceNumber(feedback.getId()).stream().map(item->new QuestionFeedbackResponse(item.getInterviewQuestion().getId(),item.getScore(),fromJson(item.getStrengths()),fromJson(item.getImprovements()),item.getRecommendation())).toList();return new FeedbackResponse(feedback.getStatus().name(),feedback.getOverallScore(),feedback.getOverallScore(),feedback.getOverallScore(),feedback.getOverallScore(),feedback.getOverallAssessment(),fromJson(feedback.getStrengths()),fromJson(feedback.getImprovementAreas()),fromJson(feedback.getRecommendedActions()),perQuestion,feedback.getGeneratedAt());}
    private String toJson(List<String> values){try{return json.writeValueAsString(values);}catch(JsonProcessingException exception){throw new IllegalStateException("Could not serialize feedback.",exception);}} private List<String> fromJson(String value){try{return value==null?List.of():json.readValue(value,json.getTypeFactory().constructCollectionType(List.class,String.class));}catch(JsonProcessingException exception){return List.of();}}
}
